import os
import json
import numpy as np
from qiskit.quantum_info import Statevector
from scipy.optimize import minimize
import qaoa_blocks


def main():
    instance = json.loads(os.environ["SUB_INSTANCE_JSON"])
    block_items = instance.get("block_items") or []
    if block_items:
        n = len(block_items)
    else:
        n = int(instance.get("num_variables", 0))

    alpha = float(instance.get("alpha", 0.5))
    beta = float(instance.get("beta", 0.5))

    times = np.array([float(it.get("time", 0.0)) for it in block_items], dtype=float)
    rates = np.array([float(it.get("rate", 0.0)) for it in block_items], dtype=float)

    global_max_time = None
    for k in ("global_max_time", "max_time", "time_max", "time_denominator"):
        v = instance.get(k)
        if v is None:
            continue
        try:
            global_max_time = float(v)
            break
        except (TypeError, ValueError):
            global_max_time = None

    global_max_rate = None
    for k in ("global_max_rate", "max_rate", "rate_max", "rate_denominator"):
        v = instance.get(k)
        if v is None:
            continue
        try:
            global_max_rate = float(v)
            break
except (TypeError, ValueError):
            global_max_rate = None

    if global_max_time is None or global_max_time <= 0:
        if times.size > 0:
            local_max_t = float(times.max())
        else:
            local_max_t = 1.0
        if local_max_t > 0:
            global_max_time = local_max_t
        else:
            global_max_time = 1.0

    if global_max_rate is None or global_max_rate <= 0:
        if rates.size > 0:
            local_max_r = float(rates.max())
else:
            local_max_r = 1.0
        if local_max_r > 0:
            global_max_rate = local_max_r
        else:
            global_max_rate = 1.0

    t_norm = times / global_max_time
    r_norm = rates / global_max_rate

    Q = np.zeros((n, n), dtype=float)
    for i in range(n):
        Q[i, i] = alpha * t_norm[i] - beta * r_norm[i]

    h, J, ising_const = qaoa_blocks.qubo_to_ising(Q)

    if not np.any(h) and not J:
        print(json.dumps({
            "value": 0.0,
"instance": {
                "type": "qubo",
                "matrix": Q.tolist(),
                "num_variables": n,
                "pauli_terms": [],
                "alpha": alpha,
                "beta": beta,
                "global_max_time": global_max_time,
                "global_max_rate": global_max_rate,
                "block_items": block_items,
            },
            "bitstring": "0" * n,
            "num_qubits": n,
            "selected_ids": [],
            "note": "all-zero block",
        }))
        return

    def cost(params):
        gamma, beta_param = params
        qc = qaoa_blocks.qaoa_diag_circuit(n, h, J, gamma, beta_param)
        sv = Statevector(qc)
        return qaoa_blocks.expectation_diag_ising(sv, n, h, J)

    x0 = np.array([0.1, 0.1])
    res = minimize(cost, x0, method="COBYLA", options={"maxiter": 20})
    if res.x is None:
        best_params = x0
    else:
        best_params = res.x

    qc = qaoa_blocks.qaoa_diag_circuit(n, h, J, best_params[0], best_params[1])
    sv = Statevector(qc)
    bitstring = qaoa_blocks.decode_bitstring(sv, n)
    x = np.array([int(b) for b in bitstring], dtype=float)
    value = float(x @ Q @ x)

    selected_ids = []
    for i in range(n):
        if x[i] > 0.5:
            selected_ids.append(block_items[i].get("id", "i" + str(i)))

    print(json.dumps({
        "value": value,
        "instance": {
            "type": "qubo",
            "matrix": Q.tolist(),
            "num_variables": n,
            "alpha": alpha,
            "beta": beta,
            "global_max_time": global_max_time,
            "global_max_rate": global_max_rate,
            "block_items": block_items,
        },
        "bitstring": bitstring,
        "num_qubits": n,
        "selected_ids": selected_ids,
        "block_index": instance.get("block_index"),
    }))


if __name__ == "__main__":
    main()

